const countryDialog=document.getElementById('countryDialog'),countryBrief=document.getElementById('countryBrief');
const countryAliases={'Cabo Verde':'Cape Verde','Congo, Democratic Republic':'DR Congo','Congo, Republic':'Congo','Côte d’Ivoire':'Ivory Coast'};
const adviceSlugs={'Congo, Democratic Republic':'democratic-republic-of-the-congo','Congo, Republic':'republic-of-the-congo','Côte d’Ivoire':'cote-d-ivoire','Gambia':'the-gambia','São Tomé and Príncipe':'sao-tome-and-principe'};
const languageCacheKey='safariPocketbookCountryLanguages';
function readLanguageCache(){try{return JSON.parse(localStorage.getItem(languageCacheKey)||'{}')}catch{return{}}}
function cacheCountryLanguages(country,languages){const cache=readLanguageCache();cache[country]={languages,savedAt:new Date().toISOString()};localStorage.setItem(languageCacheKey,JSON.stringify(cache))}
function safeText(value,fallback='Not available'){return String(value||fallback).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function adviceSlug(country){return adviceSlugs[country]||country.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function readableDate(value){if(!value)return 'Publication date unavailable';const date=new Date(value);return Number.isNaN(date.valueOf())?'Publication date unavailable':date.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}
function plainSummary(value){const text=String(value||'').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();return text.length>520?`${text.slice(0,517)}…`:text}
document.querySelector('.country-close').addEventListener('click',()=>countryDialog.close());
async function getJson(url,timeout=0){const controller=timeout?new AbortController():null,timer=controller?setTimeout(()=>controller.abort(),timeout):null;try{const response=await fetch(url,{signal:controller?.signal});if(!response.ok)throw new Error(`${response.status}`);return response.json()}finally{if(timer)clearTimeout(timer)}}
let countryReferencePromise;
async function bundledCountry(country){countryReferencePromise||=getJson('./assets/africa-country-reference.json');const data=await countryReferencePromise,row=data.countries.find(item=>item.name===(countryAliases[country]||country));if(!row)throw new Error('Bundled country reference unavailable');return{cca2:row.code,region:row.region,subregion:row.subregion,capital:row.capital,currencies:row.currencies,languages:row.languages,drivingSide:row.drivingSide,callingCode:row.callingCode}}
function languageObject(languages){return Object.fromEntries(languages.map((name,index)=>[`language${index}`,name]))}
function mountCountrySections(country,atlasRow,languages){const advisory=countryBrief.querySelector('.advisory-section');advisory?.insertAdjacentHTML('beforebegin',window.countryDepthHtml?.(country,atlasRow)||'');advisory?.insertAdjacentHTML('beforebegin',window.countryDestinationHtml?.(country,atlasRow)||'');if(country==='Botswana')advisory?.insertAdjacentHTML('beforebegin',window.botswanaCatalogueHtml?.()||'');advisory?.insertAdjacentHTML('beforebegin',window.countryLanguageHtml?.(country,languageObject(languages))||'');window.mountCountryDepth?.(country);window.mountCountryDestinations?.();window.mountBotswanaCatalogue?.();window.mountCountryLanguage?.(country)}
function renderCountry(country,data,atlasRow,populationRow=null,advice=null){
 const slug=adviceSlug(country),capital=data.capital.join(', '),currencies=data.currencies.join(', '),languages=data.languages.join(', '),pending=populationRow===null&&advice===null,adviceDate=advice?.public_updated_at||advice?.details?.public_updated_at;
 countryBrief.innerHTML=`<div class="country-hero"><p class="eyebrow">AFRICAN SAFARI POCKETBOOK</p><h2>${safeText(country)}</h2><p>${safeText(data.region)} · ${safeText(data.subregion)}</p><div class="source-status"><span></span>Offline reference ready</div></div><section class="entry-section"><div class="entry-kicker">REFERENCE</div><h3>Country essentials</h3><div class="country-facts"><div><small>Capital</small><strong>${safeText(capital)}</strong></div><div><small>Population</small><strong>${populationRow?.value?Number(populationRow.value).toLocaleString():'Check online'}</strong><em>${populationRow?`World Bank · ${safeText(populationRow.date)}`:'Live field'}</em></div><div><small>Currency</small><strong>${safeText(currencies)}</strong></div><div><small>Languages</small><strong>${safeText(languages)}</strong></div><div><small>Driving side</small><strong>${safeText(data.drivingSide)}</strong></div><div><small>Calling code</small><strong>${safeText(data.callingCode)}</strong></div></div><p class="source-note">General reference fields are bundled for offline use and may lag official changes.</p></section><section class="entry-section"><div class="entry-kicker">DISCOVER</div><h3>Safari and nature highlights</h3><p>${safeText(atlasRow?.[2],'Destination information is being expanded.')}</p><p class="editorial-label">Curated Pocketbook index · Confirm access, permits, seasonality and operating status locally.</p></section><section class="entry-section advisory-section"><div class="entry-kicker live">LIVE ADVISORY</div><h3>Political and security context</h3>${advice?`<div class="advisory-update"><strong>UK government travel advice</strong><small>Updated ${readableDate(adviceDate)}</small><p>${safeText(plainSummary(advice?.details?.change_description),'Open the current advisory for details.')}</p></div>`:`<div class="advisory-unavailable"><strong>${pending?'Checking official sources…':'Official advisory unavailable'}</strong><p>The offline profile remains available. Confirm current conditions with an official source before travel.</p></div>`}<div class="advisory-links"><a href="https://www.gov.uk/foreign-travel-advice/${slug}" target="_blank" rel="noopener">UK travel advice ↗</a><a href="https://travel.state.gov/content/travel/en/search.html?search_input=${encodeURIComponent(country)}" target="_blank" rel="noopener">US travel advisory ↗</a></div></section><section class="entry-section"><div class="entry-kicker">HEALTH</div><h3>Health preparation</h3><p>Requirements and outbreak conditions can change. Consult an authorised travel-health professional and current official guidance.</p><div class="source-links"><a href="https://www.who.int/countries/${data.cca2.toLowerCase()}/" target="_blank" rel="noopener">WHO country profile ↗</a><a href="https://www.who.int/emergencies/disease-outbreak-news" target="_blank" rel="noopener">WHO outbreak notices ↗</a></div></section><div class="source-register"><strong>Source register</strong><span>Bundled countries dataset: general reference fields and languages</span><span>World Bank: live population</span><span>GOV.UK FCDO: live travel advisory</span><small>Confirm entry and visa rules with the destination country.</small></div>`;
 mountCountrySections(country,atlasRow,data.languages);cacheCountryLanguages(country,languageObject(data.languages));
}
async function openCountryBrief(country){
 const atlasRow=(window.africanAtlas||[]).find(row=>row[0]===country),slug=adviceSlug(country);
 if(!countryDialog.open)countryDialog.showModal();countryDialog.scrollTop=0;countryDialog.dataset.country=country;
 countryBrief.innerHTML=`<div class="country-hero"><p class="eyebrow">AFRICAN SAFARI POCKETBOOK</p><h2>${safeText(country)}</h2><div class="source-status offline"><span></span>Opening offline reference</div></div>`;
 try{
  const data=await bundledCountry(country);if(countryDialog.dataset.country!==country)return;renderCountry(country,data,atlasRow);
  const [populationResult,adviceResult]=await Promise.allSettled([getJson(`https://api.worldbank.org/v2/country/${data.cca2}/indicator/SP.POP.TOTL?format=json&mrnev=1`,6000),getJson(`https://www.gov.uk/api/content/foreign-travel-advice/${slug}`,6000)]);
  if(countryDialog.dataset.country!==country)return;const population=populationResult.status==='fulfilled'?populationResult.value?.[1]?.[0]:false,advice=adviceResult.status==='fulfilled'?adviceResult.value:false;renderCountry(country,data,atlasRow,population,advice);
 }catch{
  const cached=Object.values(readLanguageCache()[country]?.languages||{});countryBrief.innerHTML=`<div class="country-hero"><p class="eyebrow">AFRICAN SAFARI POCKETBOOK</p><h2>${safeText(country)}</h2><div class="source-status offline"><span></span>Reference unavailable</div></div><section class="entry-section advisory-section"><h3>Country record could not open</h3><p>The bundled reference could not be read. Close and reopen this entry, or update the app.</p><a class="retry-brief" href="#">Try again</a></section>`;mountCountrySections(country,atlasRow,cached);countryBrief.querySelector('.retry-brief')?.addEventListener('click',event=>{event.preventDefault();openCountryBrief(country)});
 }
}
window.openCountryBrief=openCountryBrief;
